/* Shared ledger rules. Preserve original billing bases; never add annual/monthly fees to totals. */
(function(root){
 const units={total:'万元',annual:'万元/年',monthly:'万元/月'};
 function summarizeRows(rows){const grouped=new Map();for(const r of rows){if(r.voided||!Number.isSafeInteger(r.cents)||!units[r.basis])continue;grouped.set(r.basis,(grouped.get(r.basis)||0)+r.cents)}const entries=['total','annual','monthly'].filter(k=>grouped.has(k)).map(basis=>({basis,value:grouped.get(basis)/1000000,unit:units[basis]}));if(!entries.length)entries.push({basis:'total',value:0,unit:units.total});return {entries,html:entries.map(e=>e.value.toLocaleString('zh-CN',{maximumFractionDigits:6})+'<small>'+e.unit+'</small>').join('<br>')};}
 function summarize(rows){return summarizeRows(rows.filter(r=>r.kind==='contract'&&r.confirmed&&!r.voided))}
 function latest(rows,pid,cutoff){const priority={contract:3,quote:2,budget:1};return rows.map((r,i)=>({...r,order:i})).filter(r=>r.pid===pid&&!r.voided&&r.date<=cutoff&&priority[r.kind]).sort((a,b)=>priority[b.kind]-priority[a.kind]||b.date.localeCompare(a.date)||String(b.time||'').localeCompare(String(a.time||''))||String(b.recordedAt||'').localeCompare(String(a.recordedAt||''))||b.order-a.order)[0]||null}
 function snapshot(projects,rows,cutoff){const ids=new Set(projects.map(p=>p.id));const contracts=rows.filter(r=>ids.has(r.pid)&&r.date<=cutoff&&r.kind==='contract'&&r.confirmed&&!r.voided);const signedIds=new Set(contracts.map(r=>r.pid));const prospects=projects.filter(p=>!signedIds.has(p.id));const opportunities=rows.filter(r=>r.kind==='quote'||r.kind==='budget');const entries=prospects.map(p=>({p,record:latest(opportunities,p.id,cutoff)}));return {entries,contracts,signedIds,opportunity:summarizeRows(entries.map(e=>e.record).filter(Boolean)),contract:summarize(contracts),missing:entries.filter(e=>!e.record).length,pending:entries.filter(e=>e.record&&!e.record.confirmed).length}}
 root.ContractAmounts={summarize,summarizeRows,latest,snapshot};
})(globalThis);
